use bitloom_prelude::{Elaboratable,PortValues,ip::Axi4LiteSlave};
use bitloom_sim::Sim;
fn pins()->PortValues { let mut p=PortValues::default(); for n in ["rst","s_axi_awvalid","s_axi_wvalid","s_axi_arvalid","s_axi_awaddr","s_axi_araddr"] {p.set(n,0);} p.set("s_axi_bready",1);p.set("s_axi_rready",1);p.set("s_axi_wstrb",15);p.set("s_axi_wdata",0x5a);p }
fn init()->Sim {let mut s=Sim::new(Axi4LiteSlave::elaborate().unwrap());let mut p=pins();p.set("rst",1);s.set_inputs(p);s.tick();s}
#[test] fn separated_aw_w_probe(){let mut s=init();let mut p=pins();p.set("s_axi_awvalid",1);s.set_inputs(p);s.settle();assert_eq!(s.ports().get("s_axi_awready"),Some(1));s.tick();let mut p=pins();p.set("s_axi_wvalid",1);s.set_inputs(p);s.settle();assert_eq!(s.ports().get("s_axi_wready"),Some(1));s.tick();let mut seen=s.ports().get("s_axi_bvalid")==Some(1);for _ in 0..4 {s.set_inputs(pins());s.tick();seen|=s.ports().get("s_axi_bvalid")==Some(1);}println!("AW accepted before W; W accepted next cycle; observed B response over next 5 cycles={seen}");assert!(!seen,"probe records current behavior, not a passing protocol acceptance test");}
#[test] fn concurrent_read_write_probe(){let mut s=init();let mut p=pins();for n in ["s_axi_awvalid","s_axi_wvalid","s_axi_arvalid"] {p.set(n,1);}s.set_inputs(p);s.settle();assert_eq!(s.ports().get("s_axi_arready"),Some(1));assert_eq!(s.ports().get("s_axi_awready"),Some(1));assert_eq!(s.ports().get("s_axi_wready"),Some(1));s.tick();let mut seen=s.ports().get("s_axi_rvalid")==Some(1);for _ in 0..4{s.set_inputs(pins());s.tick();seen|=s.ports().get("s_axi_rvalid")==Some(1);}println!("AR accepted alongside AW/W; observed R response over next 5 cycles={seen}");assert!(!seen,"probe records current behavior, not a passing protocol acceptance test");}
